import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import moment from 'moment';
import get from 'lodash/get';
import api from 'services/api';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { redirectToVulnDetail } from 'store/Manage/actions';
import { redirect } from 'store/Router/actions';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import { Empty, LinkButton } from '../common/styled';
import TitleWrapper from '../components/TitleWrapper';
import {
  Wrapper,
  StatsRow,
  StatItem,
  StatValue,
  StatLabel,
  ContentWrapper,
  CredentialItem,
  CredentialInfo,
  CredentialEndpoint,
  CredentialSubtext,
  PasswordRedaction,
  VulnLinkIcon,
  StatusText,
  CredentialsIcon
} from './styled';
import {
  CREDENTIALS_LIST_QUERY,
  CREDENTIALS_OWNED_QUERY,
  CREDENTIALS_LEAKED_QUERY,
  MASKED_PASSWORD
} from './constants';

const getSeverity = (isOwned, isLeaked) => {
  if (isOwned) return 'owned';
  if (isLeaked) return 'leaked';
  return undefined;
};

const CredentialsSummary = () => {
  const dispatch = useDispatch();
  const workspaceSelected = useSelector(selectCurrentWorkspace);

  const [credentials, setCredentials] = useState([]);
  const [stats, setStats] = useState({ total: 0, owned: 0, leaked: 0 });
  const [isFetching, setIsFetching] = useState(false);
  const [hasError, setHasError] = useState(false);

  const intl = useIntl();
  const translations = useMemo(
    () => ({
      title: intl.formatMessage({ id: 'dashboard.widgets.credentials.title' }),
      empty: intl.formatMessage({ id: 'dashboard.widgets.credentials.empty' }),
      error: intl.formatMessage({ id: 'dashboard.widgets.credentials.error' }),
      collected: intl.formatMessage({ id: 'dashboard.widgets.credentials.collected' }),
      validated: intl.formatMessage({ id: 'dashboard.widgets.credentials.validated' }),
      inBreachDumps: intl.formatMessage({ id: 'dashboard.widgets.credentials.inBreachDumps' }),
      viewAll: intl.formatMessage({ id: 'dashboard.widgets.credentials.viewAll' }),
      owned: intl.formatMessage({ id: 'dashboard.widgets.credentials.owned' }),
      leaked: intl.formatMessage({ id: 'dashboard.widgets.credentials.leaked' }),
      collectedHint: intl.formatMessage({ id: 'dashboard.widgets.credentials.collectedHint' }),
      validatedHint: intl.formatMessage({ id: 'dashboard.widgets.credentials.validatedHint' }),
      breachHint: intl.formatMessage({ id: 'dashboard.widgets.credentials.breachHint' })
    }),
    [intl]
  );

  const exposedByLabel = (vulnName) => intl.formatMessage(
    { id: 'dashboard.widgets.credentials.exposedBy' },
    { vulnName }
  );

  useEffect(() => {
    let mounted = true;

    const fetchCredentials = async () => {
      setIsFetching(true);

      const [listResult, ownedResult, leakedResult] = await Promise.allSettled([
        api.credentials.getCredentials(workspaceSelected, CREDENTIALS_LIST_QUERY),
        api.credentials.getCredentials(workspaceSelected, CREDENTIALS_OWNED_QUERY),
        api.credentials.getCredentials(workspaceSelected, CREDENTIALS_LEAKED_QUERY)
      ]);

      if (!mounted) return;

      const anyRejected = [listResult, ownedResult, leakedResult].some(
        (result) => result.status === 'rejected'
      );

      if (anyRejected) {
        setHasError(true);
        setCredentials([]);
        setStats({ total: 0, owned: 0, leaked: 0 });
      } else {
        setHasError(false);
        setCredentials(get(listResult.value, 'rows', []));
        setStats({
          total: get(listResult.value, 'count', 0),
          owned: get(ownedResult.value, 'count', 0),
          leaked: get(leakedResult.value, 'count', 0)
        });
      }

      setIsFetching(false);
    };

    if (workspaceSelected) fetchCredentials();

    return () => {
      mounted = false;
    };
  }, [workspaceSelected]);

  const goToCredentials = () => dispatch(redirect(`/credentials/${workspaceSelected}`));

  const goToVuln = (vulns) => {
    if (vulns.length === 1) dispatch(redirectToVulnDetail(vulns[0].id));
  };

  const handleActivateKey = (event, vulns) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    goToVuln(vulns);
  };

  if (isFetching) return <SpinnerComponent height="250px" />;

  let content;
  if (hasError) {
    content = <Empty>{translations.error}</Empty>;
  } else if (stats.total === 0) {
    content = <Empty>{translations.empty}</Empty>;
  } else {
    content = (
      <>
        <StatsRow>
          <StatItem title={ translations.collectedHint }>
            <StatValue>{stats.total}</StatValue>
            <StatLabel>{translations.collected}</StatLabel>
          </StatItem>
          <StatItem $severity={ stats.owned > 0 ? 'owned' : undefined } title={ translations.validatedHint }>
            <StatValue>{stats.owned}</StatValue>
            <StatLabel>{translations.validated}</StatLabel>
          </StatItem>
          <StatItem $severity={ stats.leaked > 0 ? 'leaked' : undefined } title={ translations.breachHint }>
            <StatValue>{stats.leaked}</StatValue>
            <StatLabel>{translations.inBreachDumps}</StatLabel>
          </StatItem>
        </StatsRow>
        <ContentWrapper>
          {credentials.map((credential) => {
            const data = credential.value ?? {};
            const vulns = data.vulnerabilities ?? [];
            const canRedirect = vulns.length === 1;
            const isOwned = !!data.owned;
            const isLeaked = !isOwned && !!data.leak_date;
            const severity = getSeverity(isOwned, isLeaked);

            return (
              <CredentialItem
                key={ credential.id }
                onClick={ () => canRedirect && goToVuln(vulns) }
                onKeyDown={ canRedirect ? (event) => handleActivateKey(event, vulns) : undefined }
                role={ canRedirect ? 'button' : undefined }
                tabIndex={ canRedirect ? 0 : undefined }
                $clickable={ canRedirect }
                $severity={ severity }
                title={ canRedirect ? exposedByLabel(vulns[0].name) : undefined }
              >
                <CredentialInfo>
                  <CredentialEndpoint title={ data.endpoint }>{data.endpoint}</CredentialEndpoint>
                  <CredentialSubtext>
                    {data.username}
                    {data.password && (
                      <>
                        {' · '}
                        <PasswordRedaction>{MASKED_PASSWORD}</PasswordRedaction>
                      </>
                    )}
                  </CredentialSubtext>
                  {severity && (
                    <StatusText $severity={ severity }>
                      {isOwned
                        ? translations.owned
                        : `${translations.leaked} · ${moment(data.leak_date).fromNow()}`}
                    </StatusText>
                  )}
                </CredentialInfo>
                <VulnLinkIcon $visible={ canRedirect } />
              </CredentialItem>
            );
          })}
        </ContentWrapper>
      </>
    );
  }

  return (
    <Wrapper>
      <TitleWrapper
        title={ translations.title }
        info={ <LinkButton onClick={ goToCredentials }>{translations.viewAll}</LinkButton> }
        icon={ <CredentialsIcon /> }
      />
      {content}
    </Wrapper>
  );
};

export default CredentialsSummary;
